import React, { Suspense } from 'react'
import { Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom'
import BotonPerfil from '../../Componentes/BotonPerfil/BotonPerfil';
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages'
import './Datos.css';
import Boton from '../../Componentes/Boton/Boton';
import { useValidarSesion } from '../../hooks/useValidarSesion';
import { useState } from "react";
import ResetearContrasenia from '../../Componentes/Formularios/ResetearContrasenia/ResetearContrasenia';
import Modal from '../../Componentes/Modal/Modal';

export default function Datos() {

    const { storeCargado, token, usuario } = useValidarSesion(); // obtener el token desde Zustand 
    const [mostrarCambiarContrasenia, setMostrarCambiarContrasenia] = useState(false);

    const modalModificarContrasenia = () => {
        setMostrarCambiarContrasenia(!mostrarCambiarContrasenia);
    }

    /////////////NAVEGAR HACIA PERFIL   
    const navegarHacia = useNavigate();
    const clickVender = () => {
        navegarHacia('/vender');
    }


    const clickCambiarContra = () => {
        navegarHacia('/resetear');
    }


    const location = useLocation(); // Obtener la ruta actual para resaltar la pestaña activa

    const navItems = [
        { path: "/perfil", label: "Datos" },
        { path: "/perfil/configuraciones", label: "Configurar" },
    ];
    const urlImg = `url("${'https://http2.mlstatic.com/D_NQ_NP_884067-MLA53246821009_012023-O.webp'}")`;

    const header = <>
        <div className='__panel_perfil'>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                <span className='__usuario_imagen' style={{ backgroundImage: urlImg }} ></span>
                <h1 style={{color:'white', fontSize: '4rem'}}>DATOS</h1>
            </div>

        </div>
    </>


    const navigation = <>
        <ul className="__pestanias">
            {navItems.map((item) => (
                <li
                    key={item.path}
                    className={location.pathname === item.path ? "active disabled" : ""}
                >
                    <Link to={item.path}>{item.label}</Link>
                </li>
            ))}
        </ul>


    </>



    const main = (
        <div className="__plantilla_configuraciones">

            <div className='__cuerpo_datos'>
                <h1>Datos del Usuario</h1>

                <Modal titulo="Cambiar Contraseña" visible={mostrarCambiarContrasenia} funcion={modalModificarContrasenia} anchura="70rem" altura="10s0rem">
                    <ResetearContrasenia
                        tokenProp={token}
                        correoProp={usuario.correo}
                        modo="cambio"
                        onCerrar={modalModificarContrasenia}
                    />
                </Modal>

                <ul className='__datos'>
                    <li>{`Nombre y Apellido: ${usuario.nombre} ${usuario.apellido}`}</li>
                    <li>{`Correo: ${usuario.correo}`}</li>
                    <li>{`DNI: ${usuario.dni}`}</li>
                    <li>
                        <span>¿Cambiar contraseña?</span>
                        <Boton
                            descripcion="Cambiar"
                            habilitado
                            onClick={modalModificarContrasenia}
                        />
                    </li>
                </ul>

            </div>
        </div>
    );




    return <PlantillaPages
        header={header}
        navigation={navigation}
        main={main}
        nombreUsuario={usuario?.nombre}
        apellidoUsuario={usuario?.apellido}
        sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
        rol={usuario?.rol?.[0]?.nombreRol}
        esSuperAdmin={usuario?.rol?.[0]?.nombreRol === "superadmin"}
        configuraciones

    />;
}